export const meta = {
  name: 'move-reencrypt-completeness',
  description: 'Verify the moveItem re-encrypt fix and check whether bin-restore, shared-folder, and batch/folder moves carry the same decrypt-after-move bug',
  phases: [{ title: 'Probe' }, { title: 'Synthesize' }],
}

const REPO = '/Users/myankelev/Code/random/cipher-box'

const CONTEXT = `
REPO: ${REPO} (on branch main).

CONFIRMED BUG + FIX (just applied by a debug session):
Root cause: a file's FileMetadata IPNS record is AES-256-GCM encrypted with its PARENT folder's folderKey at upload time (packages/sdk-core/src/file/index.ts:136, createFileMetadata uses params.folderKey). The decrypt path (download/preview/edit) resolves with the CURRENT parent folder's folderKey (apps/web .../useFileBrowserActions.ts download; useStreamingPreview.ts). So when a FilePointer is re-parented to a folder with a different folderKey WITHOUT re-encrypting its FileMetadata, decrypt uses the wrong key → "CryptoError: Decryption failed".

The fix (packages/sdk/src/client.ts, CipherBoxClient.moveItem ~696-756): after sdkCore.moveItem shuffles the FilePointer between folders, if the moved child is a FilePointer it (1) unwraps the file IPNS private key from FilePointer.ipnsPrivateKeyEncrypted with the vault keypair, (2) resolves current FileMetadata using source.folderKey, (3) calls sdkCore.updateFileMetadata with folderKey=dest.folderKey, createVersion=false to re-publish the IPNS record under the destination key. Regression test: packages/sdk/src/__tests__/client-move-reencrypt.test.ts.

The debugger flagged these UNVERIFIED blind spots — any path that RE-PARENTS a file to a folder with a different folderKey but doesn't re-encrypt FileMetadata has the SAME bug:
- bin restore (restoreFromBin): does restoring a file from the bin re-parent it (possibly to a different folder than it came from, or to root) without re-encrypting?
- shared-folder writes/moves (useSharedWriteOps: renameInSharedFolder / move within or into/out of a shared folder): same re-encrypt gap?
- batch/multi-select move, and FOLDER move (moving a folder that CONTAINS files): does multi-move route through the fixed moveItem per item? Does moving a FOLDER need anything (its children stay under the same subfolder folderKey, so likely fine — confirm)?
`

const SIBLING_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    path_name: { type: 'string' },
    affected: { type: 'string', enum: ['yes', 'no', 'unsure'] },
    severity: { type: 'string', enum: ['data-loss', 'broken-decrypt', 'none', 'unknown'] },
    explanation: { type: 'string' },
    evidence: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: { file: { type: 'string' }, note: { type: 'string' } },
        required: ['file', 'note'],
      },
    },
    suggested_fix: { type: 'string' },
  },
  required: ['path_name', 'affected', 'severity', 'explanation', 'evidence', 'suggested_fix'],
}

const PROBES = [
  {
    key: 'bin-restore',
    prompt: `Probe the BIN RESTORE path. Find restoreFromBin / bin restore in packages/sdk/src and packages/sdk-core/src and the web hook that calls it. Determine: when a file is restored from the bin into a folder, is it re-parented to a folder whose folderKey may differ from where it was when deleted (e.g. original folder deleted → restore to root)? Does the restore re-encrypt the FileMetadata for the destination folderKey (like the new moveItem fix), or does it only move the FilePointer? If it doesn't re-encrypt and the destination key can differ, it has the same decrypt-after-restore bug. Cite file:line.`,
  },
  {
    key: 'shared-folder-move',
    prompt: `Probe the SHARED-FOLDER write/move path. Find useSharedWriteOps (apps/web) and the SDK shared-write functions (packages/sdk/src/share/shared-write.ts) — renameInSharedFolder, uploadToSharedFolder, deleteFromSharedFolder, and any move within/into/out of a shared folder. Determine whether moving a file between folders in the shared context (or moving a file into/out of a shared folder) re-encrypts FileMetadata for the destination folderKey. Note: shared folders may use a different folderKey than the owner's private tree, so a move across that boundary is exactly the at-risk case. Is there an equivalent of the moveItem fix here? Cite file:line.`,
  },
  {
    key: 'batch-and-folder-move',
    prompt: `Probe BATCH/MULTI-SELECT move and FOLDER move. (1) When the user multi-selects files and moves them, does the web layer call CipherBoxClient.moveItem once per item (so each gets the new re-encrypt fix), or is there a separate batch move path that bypasses it? Find the web move handler (e.g. useFileBrowserActions / useFolderMutations move). (2) When a FOLDER (containing files) is moved into another folder, do the contained files need re-encryption? Reason about the key model: a subfolder's files are encrypted with the SUBFOLDER's folderKey, and moving the folder carries its FolderEntry (with wrapped folderKey) — so the children's parent key is unchanged. Confirm this from code (sdkCore.moveItem / folder metadata) and state whether folder move is safe or also affected. Cite file:line.`,
  },
  {
    key: 'verify-applied-fix',
    prompt: `VERIFY THE APPLIED FIX is correct and the suite is green. Read packages/sdk/src/client.ts moveItem (~696-770) as it stands now and confirm: (a) it only re-encrypts when the moved child is a FilePointer (not a folder); (b) it resolves with SOURCE folderKey and publishes with DEST folderKey; (c) createVersion=false (a move must not create a spurious version); (d) the unwrapped file IPNS private key is zeroed after use (CLAUDE.md crypto rule) and errors are handled so a re-encrypt failure doesn't silently corrupt state; (e) it handles the no-op / same-folder move and the root-as-source/dest cases. Then RUN: \`pnpm --filter @cipherbox/sdk test\` and report pass/fail counts. Also report any obviously missing test case. Set affected='no' if the fix is correct; severity reflects any defect you find IN THE FIX. Cite file:line and paste the key test summary line.`,
  },
]

phase('Probe')
log('Probing 3 sibling re-parent paths + verifying the applied fix...')
const probes = await parallel(
  PROBES.map((p) => () =>
    agent(`${CONTEXT}\n\nYOUR TASK — ${p.key}:\n${p.prompt}\n\nGround every claim in real file:line. If a path does not re-encrypt and the destination key can differ, mark affected='yes'. Be decisive.`, {
      label: `probe:${p.key}`,
      phase: 'Probe',
      // verify-applied-fix needs Bash to run the suite; the 3 read-only probes use Explore.
      agentType: p.key === 'verify-applied-fix' ? 'general-purpose' : 'Explore',
      schema: SIBLING_SCHEMA,
    })
  )
)
const clean = probes.filter(Boolean)

phase('Synthesize')
const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    fix_is_correct: { type: 'boolean' },
    suite_green: { type: 'boolean' },
    complete_for_pr: { type: 'boolean', description: 'true if no sibling path shares the bug; false if more fixes are needed' },
    affected_siblings: { type: 'array', items: { type: 'string' } },
    recommended_followups: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['fix_is_correct', 'suite_green', 'complete_for_pr', 'affected_siblings', 'recommended_followups', 'summary'],
}
const verdict = await agent(
  `${CONTEXT}\n\nProbe results:\n\n${JSON.stringify(clean, null, 2)}\n\nSynthesize: Is the applied moveItem fix correct and the suite green? Do any of bin-restore / shared-folder-move / batch-folder-move share the SAME decrypt-after-reparent bug (affected='yes')? Decide complete_for_pr (true only if NO sibling path is affected). List affected siblings and concrete recommended follow-ups (each as "path: what to fix"). Ground in the probe evidence; don't invent affected paths the probes rated 'no'.`,
  { label: 'synthesize', phase: 'Synthesize', schema: VERDICT_SCHEMA }
)
return { verdict, probes: clean }

